//! `Utf8View` string columns built straight from generated bytes.

use arrow_array::{ArrayRef, StringViewArray};
use arrow_buffer::{Buffer, NullBuffer, ScalarBuffer};
use std::sync::Arc;

/// A string column being built: views, and one data buffer for strings
/// longer than 12 bytes (shorter ones live in their view).
pub(crate) struct Views {
    views: Vec<u128>,
    data: Vec<u8>,
}

impl Views {
    /// Room for `n` strings of `bytes` bytes in all.
    pub(crate) fn with_capacity(n: usize, bytes: usize) -> Self {
        Views {
            views: Vec::with_capacity(n),
            data: Vec::with_capacity(bytes),
        }
    }

    /// Append a string of `len` ASCII bytes, written by `fill`.
    #[inline(always)]
    pub(crate) fn push_with(&mut self, len: usize, fill: impl FnOnce(&mut [u8])) {
        if len <= 12 {
            let mut b = [0u8; 16];
            fill(&mut b[..len]);
            // inline view: length, then the bytes, zero padded
            let v = u128::from_le_bytes(b) << 32 | len as u128;
            self.views.push(v);
        } else {
            let at = self.data.len();
            self.data.resize(at + len, 0);
            let s = &mut self.data[at..];
            fill(s);
            let prefix = u32::from_le_bytes([s[0], s[1], s[2], s[3]]);
            assert!(at <= u32::MAX as usize, "batch string data over 4 GiB");
            self.views
                .push(len as u128 | (prefix as u128) << 32 | (at as u128) << 96);
        }
    }

    /// Append `s` (ASCII).
    #[inline(always)]
    pub(crate) fn push(&mut self, s: &[u8]) {
        self.push_with(s.len(), |b| b.copy_from_slice(s))
    }

    pub(crate) fn finish(self) -> ArrayRef {
        self.finish_nulls(None)
    }

    pub(crate) fn finish_nulls(self, nulls: Option<NullBuffer>) -> ArrayRef {
        let buffers = if self.data.is_empty() {
            Arc::from(vec![])
        } else {
            Arc::from(vec![Buffer::from_vec(self.data)])
        };
        // SAFETY: every view was built by `push_with` from ASCII bytes:
        // inline, or at its offset in buffer 0 with its prefix.
        Arc::new(unsafe {
            StringViewArray::new_unchecked(ScalarBuffer::from(self.views), buffers, nulls)
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use arrow_array::Array;

    #[test]
    fn views_round_trip() {
        let words = [
            "",
            "a",
            "twelve bytes",
            "thirteen byte",
            "a longer string than that",
        ];
        let mut v = Views::with_capacity(words.len(), 64);
        for w in words {
            v.push(w.as_bytes());
        }
        let a = v.finish();
        let a = a.as_any().downcast_ref::<StringViewArray>().expect("view");
        a.to_data().validate_full().expect("valid");
        let got: Vec<&str> = a.iter().map(|s| s.expect("non-null")).collect();
        assert_eq!(got, words);
    }
}
